/* GENERATED by gen_hcon_vault.py -- models are generated.
   SAT_QUOTE_HEADER
   anchor      : HUB_QUOTE   (kind: hub, origin: map.anchor)
   track       : ratified
   history     : SCD2
   feeders     : 6 emitted of 6 (one per source view AND run)
   runs        : 3 -- opus_health_delta3, opus_health_legacy_v4, opus_health_v2
   payload     : 5 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_QUOTE_HK
   hashdiff    : SAT_QUOTE_HEADER_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
   CROSS-RUN RECONCILIATION, DECLARED (carve-out ratified by the mapping counterparty):
   this satellite's anchor is one of the shared objects written by BOTH runs, whose two
   identifier registries are UNRECONCILED. The declared source precedence below is a VALUE
   CHOICE APPLIED TO ROWS THAT MAY REPRESENT TWO UNRECONCILED POPULATIONS -- two writers may
   be describing one entity, or two different parties colliding in one key space, and which
   it is cannot be settled from the map, the model or the SQL.
   WHY THE SCOPE IS EVERY SHARED OBJECT AND NOT A LOW-OVERLAP SUBSET: a hub-level
   business-key-column overlap cannot see the hazard at any threshold. HUB_PARTY's overlap
   of three is IMD_CODE, PART_ID and RM_CODE, all intermediary-side; on the member/customer
   population the overlap is ZERO. The figure is unstable too -- collapsing underscores moves
   it from three to five.
   WHY DECLARE RATHER THAN REFUSE: the choice is made on ASYMMETRY. A DECLARED CONFLICT IS
   RECOVERABLE; A WRONG MERGE IS NOT, AFTER LOAD. That is the justification, not a
   preference.
   The subordinate writer and its registry are NAMED below so the loss is COUNTABLE.
   A load-time assertion in models/assertions/ counts the hash keys actually written by both
   runs. Until it runs, whether the precedence EVER fires is UNKNOWN, not zero.
     SUBORDINATE WRITER on QUOTE_DATE: run opus_health_legacy_v4, 1 writer(s), registry/ies HUB_QUOTE_BK__QUOTE_REF, HUB_QUOTE_BK__QUOTE_REF_NO, HUB_QUOTE_BK__QUOTE_SUB_NO -- its value is DISCARDED wherever opus_health_v2 also writes the same key
   DECLARED SOURCE PRECEDENCE -- 1 attribute(s) are written by BOTH runs.
   Never a key change and never RECORD_SOURCE in a key: either would
   silently alter grain. Precedence is a VALUE choice, reversible by reload:
     QUOTE_DATE                                   opus_health_v2 > opus_health_legacy_v4
   INTRA-RUN FAN-IN, 2 attribute/run pair(s) with more than one writer, of
   which 2 are genuinely ARBITRARY. WITHIN one run several source views
   write the same attribute and the map declares NO precedence among them,
   so max() picks arbitrarily -- BUT ONLY AMONG UNDISCRIMINATED WRITERS. A
   writer carrying a resolved `instance` or a declared `redundant_of` is
   SEPARATED, not competing: a nominee's name and a policyholder's name on
   one satellite are DIFFERENT ROWS. BOTH SCOPES are quoted below because a
   bare writer count overstates the arbitrariness -- on PARTY_FULL_NAME it
   overstates it nearly fivefold.
   DECLARED, NOT RESOLVED: choosing among same-run writers would invent an
   authority the map does not provide. NO CROSS-RUN DECISION REACHES THIS.
     QUOTE_STATUS                           opus_health_legacy_v4  5 writer(s), of which 3 UNDISCRIMINATED (0 separated by a resolved instance, 2 by redundant_of)  [CROSS-TABLE: check_collapse groups on (table, satellite, attribute, instance, child_key) and CANNOT see this]
     QUOTE_VERSION                          opus_health_delta3     2 writer(s), of which 2 UNDISCRIMINATED (0 separated by a resolved instance, 0 by redundant_of)  [CROSS-TABLE: check_collapse groups on (table, satellite, attribute, instance, child_key) and CANNOT see this]
   A load-time assertion in models/assertions/ counts the DISTINCT
   values the undiscriminated writers actually supply per key. Until it
   runs, whether they ever disagree is UNKNOWN, not zero.
*/

with feeders as (
    select
        md5(upper('HUB_QUOTE|' || (HUB_QUOTE_BK__QUOTE_REF))) as HUB_QUOTE_HK
        , QUOTE_STATUS as QUOTE_STATUS
        , cast(null as varchar) as REQUESTED_COVER_START_DATE
        , cast(null as varchar) as QUOTE_REMARKS
        , cast(null as varchar) as QUOTE_DATE
        , cast(null as varchar) as QUOTE_VERSION
        , 'BJAZ_ECARD_POL_DTLS_CONFIG' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ecard_pol_dtls_config') }}
    where (nullif(trim(QUOTE_REF),'')) is not null
    union all
    select
        md5(upper('HUB_QUOTE|' || (HUB_QUOTE_BK__QUOTE_SUB_NO))) as HUB_QUOTE_HK
        , QUOTE_STATUS_DESC as QUOTE_STATUS
        , START_DATE as REQUESTED_COVER_START_DATE
        , REMARKS as QUOTE_REMARKS
        , REGISTER_DATE as QUOTE_DATE
        , cast(null as varchar) as QUOTE_VERSION
        , 'BJAZ_GRP_HLT_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_grp_hlt_dtls') }}
    where (nullif(trim(QUOTE_SUB_NO),'')) is not null
    union all
    select
        md5(upper('HUB_QUOTE|' || (HUB_QUOTE_BK__QUOTE_REF_NO))) as HUB_QUOTE_HK
        , QUOTE_STATUS as QUOTE_STATUS
        , cast(null as varchar) as REQUESTED_COVER_START_DATE
        , cast(null as varchar) as QUOTE_REMARKS
        , cast(null as varchar) as QUOTE_DATE
        , cast(null as varchar) as QUOTE_VERSION
        , 'BJAZ_HG_POL_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hg_pol_dtls') }}
    where (nullif(trim(QUOTE_REF_NO),'')) is not null
    union all
    select
        md5(upper('HUB_QUOTE|' || (HUB_QUOTE_BK__QUOTATION_NO))) as HUB_QUOTE_HK
        , cast(null as varchar) as QUOTE_STATUS
        , cast(null as varchar) as REQUESTED_COVER_START_DATE
        , cast(null as varchar) as QUOTE_REMARKS
        , RECORD_DATE as QUOTE_DATE
        , cast(null as varchar) as QUOTE_VERSION
        , 'BJAZ_ENROLL_SCR_DTLS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_enroll_scr_dtls') }}
    where (nullif(trim(QUOTATION_NO),'')) is not null
    union all
    select
        md5(upper('HUB_QUOTE|' || (HUB_QUOTE_BK__quote_no))) as HUB_QUOTE_HK
        , cast(null as varchar) as QUOTE_STATUS
        , cast(null as varchar) as REQUESTED_COVER_START_DATE
        , cast(null as varchar) as QUOTE_REMARKS
        , cast(null as varchar) as QUOTE_DATE
        , quote_sub_no as QUOTE_VERSION
        , 'BJAZ_GRP_HLT_COVERAGE_DTLS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_grp_hlt_coverage_dtls') }}
    where (nullif(trim(quote_no),'')) is not null
    union all
    select
        md5(upper('HUB_QUOTE|' || (HUB_QUOTE_BK__QUOTE_NO))) as HUB_QUOTE_HK
        , cast(null as varchar) as QUOTE_STATUS
        , cast(null as varchar) as REQUESTED_COVER_START_DATE
        , cast(null as varchar) as QUOTE_REMARKS
        , cast(null as varchar) as QUOTE_DATE
        , QUOTE_SUB_NO as QUOTE_VERSION
        , 'BJAZ_GRP_HLT_MEM_DTLS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_grp_hlt_mem_dtls') }}
    where (nullif(trim(QUOTE_NO),'')) is not null
),

resolved as (
    select
        HUB_QUOTE_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then QUOTE_STATUS end) as QUOTE_STATUS,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then REQUESTED_COVER_START_DATE end) as REQUESTED_COVER_START_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then QUOTE_REMARKS end) as QUOTE_REMARKS,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then QUOTE_DATE end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then QUOTE_DATE end)) as QUOTE_DATE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then QUOTE_VERSION end) as QUOTE_VERSION,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_QUOTE_HK
),

hashed as (
    select
        *,
        case when QUOTE_STATUS is not null or REQUESTED_COVER_START_DATE is not null or QUOTE_REMARKS is not null or QUOTE_DATE is not null or QUOTE_VERSION is not null
                     then md5(upper(coalesce(cast(QUOTE_STATUS as varchar), '') || '|' || coalesce(cast(REQUESTED_COVER_START_DATE as varchar), '') || '|' || coalesce(cast(QUOTE_REMARKS as varchar), '') || '|' || coalesce(cast(QUOTE_DATE as varchar), '') || '|' || coalesce(cast(QUOTE_VERSION as varchar), '')))
                end as SAT_QUOTE_HEADER_HASHDIFF
    from resolved
)

select * from hashed
where HUB_QUOTE_HK is not null
  and SAT_QUOTE_HEADER_HASHDIFF is not null
